-- halo metadata schema for PostgreSQL 16+.
-- Translated from scripts/halodb_schema.sql (MySQL/MariaDB).
--
-- Type mapping (MySQL -> PG):
--   INT UNSIGNED            -> BIGINT
--   INT UNSIGNED AI         -> BIGINT GENERATED BY DEFAULT AS IDENTITY
--   TINYINT [UNSIGNED]      -> SMALLINT
--   SMALLINT UNSIGNED       -> INTEGER (SMALLINT overflows at 32767)
--   BIGINT UNSIGNED         -> NUMERIC(20,0)
--   CHAR/VARCHAR(n)         -> same, except variable-length CHAR becomes VARCHAR
--   TINYTEXT/TEXT           -> TEXT
--   VARBINARY(n)            -> BYTEA
--   DECIMAL(18,4)           -> NUMERIC(18,4)
--   DATETIME                -> TIMESTAMPTZ (always UTC, see DSN time_zone)
--
-- Timestamp writes are DB-managed, mirroring MySQL: create_at defaults to
-- now(), UPDATE statements set update_at = NOW() explicitly (PG has no
-- ON UPDATE clause). INSERTs omit both columns.

DROP TABLE IF EXISTS mm_avatars;
CREATE TABLE mm_avatars (
    avatar_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    uuid      CHAR(36) NOT NULL,
    url       VARCHAR(75) NOT NULL,
    version   BIGINT NOT NULL,
    update_at TIMESTAMPTZ NULL DEFAULT NULL,
    create_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT uq_mm_avatars_uuid UNIQUE (uuid),
    CONSTRAINT uq_mm_avatars_url UNIQUE (url)
);
COMMENT ON TABLE mm_avatars IS '头像表';

DROP TABLE IF EXISTS mm_comments;
CREATE TABLE mm_comments (
    comment_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    uuid       CHAR(36) NOT NULL,
    content    TEXT NOT NULL,
    ticket_id  BIGINT NOT NULL,
    user_id    BIGINT NOT NULL,
    version    BIGINT NOT NULL,
    update_at  TIMESTAMPTZ NULL DEFAULT NULL,
    create_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT uq_mm_comments_uuid UNIQUE (uuid)
);
CREATE INDEX idx_mm_comments_ticket_id ON mm_comments (ticket_id);
CREATE INDEX idx_mm_comments_user_id ON mm_comments (user_id);
COMMENT ON TABLE mm_comments IS '审核意见表';

DROP TABLE IF EXISTS mm_crons;
CREATE TABLE mm_crons (
    cron_id   BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    uuid      CHAR(36) NOT NULL,
    status    CHAR(1) NOT NULL,
    name      VARCHAR(75) NOT NULL,
    cmd       VARCHAR(75) NOT NULL,
    params    VARCHAR(150) NOT NULL,
    last_run  VARCHAR(25) NULL,
    next_run  VARCHAR(25) NULL,
    "interval" VARCHAR(20) NULL,
    duration  VARCHAR(20) NULL,
    recurrent SMALLINT NULL,
    hash      VARCHAR(60) NULL,
    version   BIGINT NOT NULL,
    update_at TIMESTAMPTZ NULL DEFAULT NULL,
    create_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT uq_mm_crons_uuid UNIQUE (uuid)
);
COMMENT ON TABLE mm_crons IS '计划任务表';

DROP TABLE IF EXISTS mm_glossaries;
CREATE TABLE mm_glossaries (
    "group"     VARCHAR(25) NOT NULL,
    "key"       SMALLINT NOT NULL,
    value       VARCHAR(50) NOT NULL,
    uuid        CHAR(36) NOT NULL,
    description VARCHAR(150) NOT NULL,
    version     BIGINT NOT NULL,
    update_at   TIMESTAMPTZ NULL DEFAULT NULL,
    create_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY ("group", "key"),
    CONSTRAINT uq_mm_glossaries_group_value UNIQUE ("group", value),
    CONSTRAINT uq_mm_glossaries_uuid UNIQUE (uuid)
);
COMMENT ON TABLE mm_glossaries IS '字典表';

DROP TABLE IF EXISTS mm_clusters;
CREATE TABLE mm_clusters (
    cluster_id  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    uuid        CHAR(36) NOT NULL,
    host        VARCHAR(150) NOT NULL,
    alias       VARCHAR(75) NOT NULL,
    ip          VARCHAR(15) NOT NULL,
    port        BIGINT NOT NULL DEFAULT 3306,
    "user"      VARCHAR(50) NOT NULL,
    "type"      VARCHAR(20) NOT NULL DEFAULT 'mysql',
    password    BYTEA NOT NULL,
    fingerprint BYTEA NOT NULL,
    status      SMALLINT NOT NULL DEFAULT 1,
    version     BIGINT NOT NULL,
    update_at   TIMESTAMPTZ NULL DEFAULT NULL,
    create_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT uq_mm_clusters_uuid UNIQUE (uuid),
    CONSTRAINT uq_mm_clusters_alias UNIQUE (alias),
    CONSTRAINT uq_mm_clusters_host_port UNIQUE (host, port),
    CONSTRAINT uq_mm_clusters_ip_port UNIQUE (ip, port)
);
COMMENT ON TABLE mm_clusters IS '群集表';

DROP TABLE IF EXISTS mm_logs;
CREATE TABLE mm_logs (
    log_id    BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    uuid      CHAR(36) NOT NULL,
    user_id   BIGINT NOT NULL DEFAULT 0,
    operation TEXT NOT NULL,
    version   BIGINT NOT NULL,
    create_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT uq_mm_logs_uuid UNIQUE (uuid)
);
CREATE INDEX idx_mm_logs_user_create ON mm_logs (user_id, create_at);
COMMENT ON TABLE mm_logs IS '日志表';

DROP TABLE IF EXISTS mm_options;
CREATE TABLE mm_options (
    name        VARCHAR(50) PRIMARY KEY,
    uuid        CHAR(36) NOT NULL,
    parameter   TEXT NOT NULL,
    description VARCHAR(75) NOT NULL,
    element     VARCHAR(15) NOT NULL DEFAULT '-',
    writable    SMALLINT NOT NULL,
    version     BIGINT NOT NULL,
    update_at   TIMESTAMPTZ NULL DEFAULT NULL,
    create_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT uq_mm_options_uuid UNIQUE (uuid)
);
COMMENT ON TABLE mm_options IS '系统选项表';

DROP TABLE IF EXISTS mm_queries;
CREATE TABLE mm_queries (
    query_id   BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    uuid       CHAR(36) NOT NULL,
    "type"     SMALLINT NOT NULL,
    cluster_id BIGINT NOT NULL,
    "database" VARCHAR(75) NOT NULL,
    content    TEXT NOT NULL,
    plan       TEXT NOT NULL,
    user_id    BIGINT NOT NULL,
    version    BIGINT NOT NULL,
    update_at  TIMESTAMPTZ NULL DEFAULT NULL,
    create_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT uq_mm_queries_uuid UNIQUE (uuid)
);
CREATE INDEX idx_mm_queries_user_id ON mm_queries (user_id);
CREATE INDEX idx_mm_queries_cluster_id ON mm_queries (cluster_id);
COMMENT ON TABLE mm_queries IS '查询表';

DROP TABLE IF EXISTS mm_edges;
CREATE TABLE mm_edges (
    edge_id       BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    uuid          CHAR(36) NOT NULL,
    "type"        BIGINT NOT NULL,
    ancestor_id   BIGINT NOT NULL,
    descendant_id BIGINT NOT NULL,
    version       BIGINT NOT NULL,
    update_at     TIMESTAMPTZ NULL DEFAULT NULL,
    create_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT uq_mm_edges_uuid UNIQUE (uuid),
    CONSTRAINT uq_mm_edges_type_anc_des UNIQUE ("type", ancestor_id, descendant_id)
);
COMMENT ON TABLE mm_edges IS '多对多关联表';

DROP TABLE IF EXISTS mm_roles;
CREATE TABLE mm_roles (
    role_id     BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    uuid        CHAR(36) NOT NULL,
    name        VARCHAR(25) NOT NULL,
    description VARCHAR(75) NOT NULL,
    version     BIGINT NOT NULL,
    update_at   TIMESTAMPTZ NULL DEFAULT NULL,
    create_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT uq_mm_roles_uuid UNIQUE (uuid),
    CONSTRAINT uq_mm_roles_name UNIQUE (name)
);
COMMENT ON TABLE mm_roles IS '角色表';

DROP TABLE IF EXISTS mm_rules;
CREATE TABLE mm_rules (
    name        VARCHAR(10) PRIMARY KEY,
    uuid        CHAR(36) NOT NULL,
    "group"     SMALLINT NOT NULL,
    description VARCHAR(75) NOT NULL,
    level       SMALLINT NOT NULL,
    vldr_group  SMALLINT NOT NULL,
    operator    VARCHAR(10) NOT NULL,
    parameters  VARCHAR(150) NOT NULL,
    bitwise     SMALLINT NOT NULL,
    func        VARCHAR(75) NOT NULL DEFAULT 'nil',
    message     VARCHAR(150) NOT NULL,
    element     VARCHAR(50) NOT NULL,
    version     BIGINT NOT NULL,
    update_at   TIMESTAMPTZ NULL DEFAULT NULL,
    create_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT uq_mm_rules_uuid UNIQUE (uuid)
);
COMMENT ON TABLE mm_rules IS '规则表';

DROP TABLE IF EXISTS mm_statements;
CREATE TABLE mm_statements (
    ticket_id     BIGINT NOT NULL,
    "sequence"    INTEGER NOT NULL,
    uuid          CHAR(36) NOT NULL,
    content       TEXT NOT NULL,
    "type"        SMALLINT NOT NULL,
    status        SMALLINT NOT NULL,
    report        TEXT NOT NULL,
    plan          TEXT NULL,
    results       TEXT NULL,
    rows_affected BIGINT NULL,
    version       BIGINT NOT NULL,
    update_at     TIMESTAMPTZ NULL DEFAULT NULL,
    create_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (ticket_id, "sequence"),
    CONSTRAINT uq_mm_statements_uuid UNIQUE (uuid)
);
COMMENT ON TABLE mm_statements IS '工单分解表';

DROP TABLE IF EXISTS mm_statistics;
CREATE TABLE mm_statistics (
    "group"   VARCHAR(36) NOT NULL,
    "key"     VARCHAR(50) NOT NULL,
    uuid      CHAR(36) NOT NULL,
    value     NUMERIC(18,4) NOT NULL,
    version   BIGINT NOT NULL,
    update_at TIMESTAMPTZ NULL DEFAULT NULL,
    create_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY ("group", "key"),
    CONSTRAINT uq_mm_statistics_uuid UNIQUE (uuid)
);
COMMENT ON TABLE mm_statistics IS '统计表';

DROP TABLE IF EXISTS mm_tickets;
CREATE TABLE mm_tickets (
    ticket_id   BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    uuid        CHAR(36) NOT NULL,
    cluster_id  BIGINT NOT NULL,
    "database"  VARCHAR(75) NOT NULL,
    subject     VARCHAR(50) NOT NULL,
    content     TEXT NOT NULL,
    status      SMALLINT NOT NULL,
    user_id     BIGINT NOT NULL,
    reviewer_id BIGINT NOT NULL,
    cron_id     BIGINT NULL,
    version     BIGINT NOT NULL,
    update_at   TIMESTAMPTZ NULL DEFAULT NULL,
    create_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT uq_mm_tickets_uuid UNIQUE (uuid),
    CONSTRAINT uq_mm_tickets_cron_id UNIQUE (cron_id)
);
CREATE INDEX idx_mm_tickets_user_id ON mm_tickets (user_id);
CREATE INDEX idx_mm_tickets_cluster_id ON mm_tickets (cluster_id);
CREATE INDEX idx_mm_tickets_reviewer_id ON mm_tickets (reviewer_id);
COMMENT ON TABLE mm_tickets IS '工单表';

DROP TABLE IF EXISTS mm_users;
CREATE TABLE mm_users (
    user_id   BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    uuid      CHAR(36) NOT NULL,
    email     VARCHAR(75) NOT NULL,
    password  VARCHAR(60) NOT NULL,
    status    SMALLINT NOT NULL,
    name      VARCHAR(15) NOT NULL,
    phone     NUMERIC(20,0) NOT NULL,
    avatar_id BIGINT NOT NULL,
    version   BIGINT NOT NULL,
    update_at TIMESTAMPTZ NULL DEFAULT NULL,
    create_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT uq_mm_users_uuid UNIQUE (uuid),
    CONSTRAINT uq_mm_users_email UNIQUE (email)
);
COMMENT ON TABLE mm_users IS '用户表';

DROP TABLE IF EXISTS mm_templates;
CREATE TABLE mm_templates (
    uuid        CHAR(36) PRIMARY KEY,
    subject     VARCHAR(100) NOT NULL,
    body        TEXT NOT NULL,
    description VARCHAR(50) NOT NULL,
    version     BIGINT NOT NULL,
    update_at   TIMESTAMPTZ NULL DEFAULT NULL,
    create_at   TIMESTAMPTZ NOT NULL DEFAULT now()
);
COMMENT ON TABLE mm_templates IS '邮件模板表';

DROP TABLE IF EXISTS mm_migrations;
CREATE TABLE mm_migrations (
    version     INTEGER NOT NULL,
    name        VARCHAR(75) NOT NULL,
    checksum    CHAR(64) NOT NULL,
    duration_ms INTEGER NOT NULL DEFAULT 0,
    success     BOOLEAN NOT NULL DEFAULT TRUE,
    apply_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (version),
    CONSTRAINT uq_mm_migrations_name UNIQUE (name)
);
COMMENT ON TABLE mm_migrations IS '迁移版本台账';
